import { ActionDefinition } from '../../../Action'
import {
    ChoiceColumn,
    ConditionsColumn,
    BooleanColumn,
    TableNameColumn,
    FieldNameColumn,
    DocumentIdColumn,
    StringColumn,
} from '../../../../db'

export const lookUpRecord = ActionDefinition({
    $id: '9d09f99587003300663ca1bb36cb0ba3',
    name: 'Look Up Record',
    description:
        'Look up a singular record on any ServiceNow table. You can configure the conditions for the record lookup. If multiple records are found, only the first record returns.',
    inputs: {
        sort_type: ChoiceColumn({
            label: 'Sort Type',
            maxLength: 32,
            default: 'sort_asc',
            choices: {
                sort_desc: {
                    label: 'z to a',
                    sequence: 2,
                },
                sort_asc: {
                    label: 'a to z',
                    sequence: 1,
                },
            },
        }),
        conditions: ConditionsColumn({
            label: 'Conditions',
        }),
        __snc_dont_fail_on_error: BooleanColumn({
            label: "Don't fail on error",
        }),
        table: TableNameColumn({
            label: 'Table',
        }),
        sort_column: FieldNameColumn({
            label: 'Order by',
        }),
        if_multiple_records_are_found_action: ChoiceColumn({
            label: 'If multiple records are found action',
            default: 'use_first_record',
            choices: {
                use_first_record: {
                    label: 'Return only the first record',
                    sequence: -1,
                },
                error: {
                    label: 'Fail the step',
                    sequence: -1,
                },
            },
        }),
    },
    outputs: {
        Table: TableNameColumn({
            label: 'Table',
        }),
        status: ChoiceColumn({
            label: 'Status',
            default: '0',
            choices: {
                0: {
                    label: 'Success',
                },
                1: {
                    label: 'Error',
                },
            },
        }),
        Record: DocumentIdColumn({
            label: 'Record',
            dependent: 'table',
        }),
        error_message: StringColumn({
            label: 'Error Message',
            maxLength: 8000,
        }),
    },
})
